"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/empty-states/variants/01-archive";
import Variant1 from "./components/empty-states/variants/02-search";
import Variant2 from "./components/empty-states/variants/03-inbox";
import Variant3 from "./components/empty-states/variants/04-board";
const variants = {"archive": Variant0,"search": Variant1,"inbox": Variant2,"board": Variant3};
export interface ArtemisEmptyStatesProps { className?: string; variant?: "archive" | "search" | "inbox" | "board"; }
export function ArtemisEmptyStates({ className, variant = "archive" }: ArtemisEmptyStatesProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }
